INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12101, 'Job 10:3', 'Job', 10, 3, '&nbsp;دا تا ته ښۀ ښکارى، چې ما په عذاب کړې، چې ما يعنې د خپلو لاسونو کار رد کړې او د بدکارو خلقو منصوبو ته ښۀ ووائې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12102, 'Job 10:4', 'Job', 10, 4, '&nbsp;ولې ستا نظر د انسانانو په شان دے؟ تۀ د انسان په شان کتل کوې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12103, 'Job 10:5', 'Job', 10, 5, '&nbsp;ستا عُمر زمونږ په شان لنډ دے څۀ؟ يا ستا کالونه د انسانانو د کالونو په شان دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12104, 'Job 10:6', 'Job', 10, 6, '&nbsp;چې تۀ زما غلطى معلوموې او زما ګناه لټوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12105, 'Job 10:7', 'Job', 10, 7, '&nbsp;اګر چې تا ته پته ده چې زۀ بې‌ګناه يم، او ستا د لاسونو نه مې هيڅ څوک نۀ شى بچ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12106, 'Job 10:8', 'Job', 10, 8, '&nbsp;ستا لاسونو ما له صورت راکړو او جوړ يې کړم، او اوس مې بېخى تباه کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12107, 'Job 10:9', 'Job', 10, 9, '&nbsp;هغه راپه ياد کړه چې تا زۀ د خټو نه جوړ کړم، او اوس به تۀ ما بيا خاورې کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12108, 'Job 10:10', 'Job', 10, 10, '&nbsp;تا زۀ د مور په خېټه کړم او زما وجود دې جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12109, 'Job 10:11', 'Job', 10, 11, '&nbsp;تا زۀ د غوښې او څرمنې نه جوړ کړم، او د هډُوکو او پټو په ذريعه دې يو ځائ وتړلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12110, 'Job 10:12', 'Job', 10, 12, '&nbsp;تا ما له ژوند او نۀ ختمېدونکې مينه راکړې ده، او تا زما د ژوند ښۀ حِفاظت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12111, 'Job 10:13', 'Job', 10, 13, '&nbsp;خو اوس ما ته پته ولګېده چې تا د ډېر وخت نه ما ته د نقصان دپاره پټه منصوبه جوړه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12112, 'Job 10:14', 'Job', 10, 14, '&nbsp;کۀ زۀ ګناه وکړم نو تۀ ما وينې، او زما ګناه تۀ نۀ معاف کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12113, 'Job 10:15', 'Job', 10, 15, '&nbsp;کۀ زۀ بدکاره يم، نو ما غمژن کړه. او کۀ زۀ صادق يم، نو خپل سر نۀ شم اوچتولے، ځکه چې زۀ د شرم سره مخ شوے يم او په غمونو کښې ډوب يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12114, 'Job 10:16', 'Job', 10, 16, '&nbsp;او کۀ زۀ خپل سر اوچتوم، نو تۀ د ازمرى په شان زما ښکار کوې، او خپل لوئ طاقت زما خِلاف استعمالوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12115, 'Job 10:17', 'Job', 10, 17, '&nbsp;تۀ خپل ګواهان زما خِلاف بيا راتازه کړې، او خپله غصه زما خِلاف زياتوې، تۀ زما خِلاف تازه دم فوجيان رالېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12116, 'Job 10:18', 'Job', 10, 18, '&nbsp;تا زۀ د مور د خېټې نه ولې راوويستلم؟ کاش چې زۀ د خلقو د سترګو د ليدو نه مخکښې مړ شوے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12117, 'Job 10:19', 'Job', 10, 19, '&nbsp;ښۀ به دا وے چې د سره پېدا شوے نۀ وے او د مور د خېټې نه سيدها قبر ته تلے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12118, 'Job 10:20', 'Job', 10, 20, '&nbsp;زما ژوند لنډ نۀ دے څۀ؟ ما پرېږده نو چې داسې يو ساعت په آرام شم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12119, 'Job 10:21', 'Job', 10, 21, '&nbsp;خو چې زۀ لاړ شم او بيا هيڅکله راواپس نۀ شم، چې تور او د تکې تورې تيارې مُلک ته لاړ شم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12120, 'Job 10:22', 'Job', 10, 22, '&nbsp;د نيمې شپې په شان تيارۀ، د لانجو مُلک ته، چرته چې رڼا هم د تيارې په شان وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12121, 'Job 11:1', 'Job', 11, 1, '&nbsp;بيا ضوفر نعماتى جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12122, 'Job 11:2', 'Job', 11, 2, '&nbsp;”د ډېرو خبرو جواب په کار نۀ دے څۀ؟ ولې يو سړے په ډېرو خبرو خپل ځان بې‌ګناه ثابتولے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12123, 'Job 11:3', 'Job', 11, 3, '&nbsp;ستا فالتو خبرې دې نور خلق غلى کړى څۀ؟ کله چې تۀ د چا سپکاوے کوې، نو څوک به تا ته ګوته نۀ نيسى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12124, 'Job 11:4', 'Job', 11, 4, '&nbsp;ځکه چې تۀ وائې چې زما عقيده ټيک ده، او زۀ د خُدائ پاک په نظر کښې صفا يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12125, 'Job 11:5', 'Job', 11, 5, '&nbsp;کاش چې خُدائ پاک کلام کړے وے، او هغۀ تا ته صفا وېنا کړے وے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12126, 'Job 11:6', 'Job', 11, 6, '&nbsp;او هغه به تا ته د حِکمت رازُونه وښائى. ځکه چې رښتينے حِکمت په ډېرو طريقو سره حاصليږى. نو بيا پوهه شه چې خُدائ پاک تا له د هغې نه کمه سزا درکوى چې څومره تۀ د ګناه په وجه حقدار يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12127, 'Job 11:7', 'Job', 11, 7, '&nbsp;ولې تۀ د خُدائ پاک هغه پټې خبرې معلومولے شې؟ او يا تۀ د قادر خُدائ حد معلومولے شې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12128, 'Job 11:8', 'Job', 11, 8, '&nbsp;دا حد د آسمان نه اوچت دے، تۀ څۀ کولے شې؟ او د مرګ د کندې نه ډُوب دے، تا ته څۀ پته ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12129, 'Job 11:9', 'Job', 11, 9, '&nbsp;د دې پېمانه د زمکې نه اوږده ده، او د سمندر نه پلنه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12130, 'Job 11:10', 'Job', 11, 10, '&nbsp;کۀ خُدائ پاک راشى او تا په قېدخانه کښې واچوى، او هغه د اِنصاف دپاره عدالت جوړ کړى، نو هغه څوک ايسارولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12131, 'Job 11:11', 'Job', 11, 11, '&nbsp;ځکه چې هغۀ ته پته ده چې څوک دوکه باز دے، او هغه يې د هرې ګناه نه خبر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12132, 'Job 11:12', 'Job', 11, 12, '&nbsp;خو يو کم عقل کس به په هغه وخت هوښيار شى، چې کله د يوې کوچاڼې نه يو انسان پېدا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12133, 'Job 11:13', 'Job', 11, 13, '&nbsp;کله چې ستا خپل زړۀ تيار شې، او لاسونه هغۀ ته اوچت کړې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12134, 'Job 11:14', 'Job', 11, 14, '&nbsp;د ګناهونو نه ځان خلاص کړې، او بدعملى د خپل کور نه ختمه کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12135, 'Job 11:15', 'Job', 11, 15, '&nbsp;نو يقيناً به بيا تۀ خپل سر بغېر د څۀ شرم نه اوچت کړې، تۀ به په امن کښې يې او نور به نۀ يرېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12136, 'Job 11:16', 'Job', 11, 16, '&nbsp;تۀ به خپل غم هېر کړې، او داسې به دې هېر شى لکه چې بيا به دې هيڅ خيال کښې نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12137, 'Job 11:17', 'Job', 11, 17, '&nbsp;او ستا ژوند به د غرمې د نمر نه زيات روښانه وى، او تيارۀ به دې هم د سحر د رڼا په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12138, 'Job 11:18', 'Job', 11, 18, '&nbsp;او ستا به اعتماد پېدا شى، ځکه چې اُميد شته، او تۀ به بچ شې او په حِفاظت کښې به آرام کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12139, 'Job 11:19', 'Job', 11, 19, '&nbsp;تۀ به څملې او هيڅ څوک به تا نۀ يروى، ډېر خلق به ستا نه د مدد اُميد ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12140, 'Job 11:20', 'Job', 11, 20, '&nbsp;خو د بد کاره خلقو سترګې به ړندې شى، او هغوئ به د تېښتې ټولې لارې خطا کړى، او هغوئ به صرف د مرګ په انتظار وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12141, 'Job 12:1', 'Job', 12, 1, '&nbsp;نو ايُوب جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12142, 'Job 12:2', 'Job', 12, 2, '&nbsp;”په دې کښې هيڅ شک نشته چې تاسو په هر څۀ پوهېږئ، او چې کله تاسو مرئ نو ستاسو پوهه به تاسو سره ختمه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12143, 'Job 12:3', 'Job', 12, 3, '&nbsp;خو زۀ هم ستاسو په شان پوهه لرم، زۀ ستاسو نه کم نۀ يم، چې تاسو څۀ وايئ نو په دې باندې هر څوک پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12144, 'Job 12:4', 'Job', 12, 4, '&nbsp;زۀ د خپلو دوستانو دپاره يوه مسخره يم، زۀ چې خُدائ پاک ته آواز کوم نو هغه زما آواز اورى، زۀ يو داسې سړے يم چې صادق او بې‌داغه يم، خو زۀ مسخره جوړ شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12145, 'Job 12:5', 'Job', 12, 5, '&nbsp;کوم خلق چې په آرام وى نو هغوئ په هغه چا پورې خندا کوى چې څوک په تکليف کښې دى، او هغه خلقو له ديکه ورکوى د چا چې پښې ښوئيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12146, 'Job 12:6', 'Job', 12, 6, '&nbsp;د ډاکوانو کورونه په امن کښې وى، او چې څوک خُدائ پاک راپاروى نو هغه محفوظ وى، اګر چې هغوئ د خُدائ پاک په ځائ په خپل طاقت باندې بهروسه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12147, 'Job 12:7', 'Job', 12, 7, '&nbsp;خو د ځناورو نه تپوس وکړئ او هغوئ به ستاسو رهنمائى وکړى، او په هوا کښې د مارغانو نه تپوس وکړئ، نو هغوئ به تاسو ته ښودنه وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12148, 'Job 12:8', 'Job', 12, 8, '&nbsp;او د زمکې د بوټو نه تپوس وکړئ، نو دا به تاسو ته ښودنه وکړى، او د سمندر کبانو نه تپوس وکړئ نو هغه به تاسو ته دا بيان وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12149, 'Job 12:9', 'Job', 12, 9, '&nbsp;ځکه چې هغوئ ټولو ته پته ده چې زما تکليف د مالِک خُدائ د طرف نه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12150, 'Job 12:10', 'Job', 12, 10, '&nbsp;د هغۀ په لاس کښې د هر ژوندى څيز ژوند دے او د هغۀ په لاس کښې د هر بشر ساه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12151, 'Job 12:11', 'Job', 12, 11, '&nbsp;ولې غوږونه د خبرو معائنه نۀ کوى لکه څنګه چې ژبه د خوراک خوند معلوموى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12152, 'Job 12:12', 'Job', 12, 12, '&nbsp;ولې حِکمت د سپين‌ږيرو سره نۀ وى څۀ؟ ولې زيات عُمر سره پوهه نۀ راځى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12153, 'Job 12:13', 'Job', 12, 13, '&nbsp;حِکمت او طاقت د خُدائ پاک سره دى، د هغۀ سره رهنمائى او پوهه شته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12154, 'Job 12:14', 'Job', 12, 14, '&nbsp;چې هغه څۀ وران کړى نو هيڅ څوک يې بيا نۀ شى جوړولے، او چې هغه کوم سړے قېدى کړى نو هغه خلاصېدلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12155, 'Job 12:15', 'Job', 12, 15, '&nbsp;کۀ هغه باران ايسار کړى، نو زمکه به اوچه شى، کۀ هغه اوبۀ راپرېږدى، نو اوبۀ به زمکه تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12156, 'Job 12:16', 'Job', 12, 16, '&nbsp;طاقت او حِکمت د هغۀ سره دے، دوکه خوړونکے او دوکه ورکوونکے د هغۀ د اختيار لاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12157, 'Job 12:17', 'Job', 12, 17, '&nbsp;هغه د مشرانو نه پوهه اخلى، او د قاضيانو نه کم عقلان جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12158, 'Job 12:18', 'Job', 12, 18, '&nbsp;هغه د بادشاهانو نه اختيار واخلى، او د هغوئ نه غلامان جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12159, 'Job 12:19', 'Job', 12, 19, '&nbsp;هغه اِمامان شړى او اختيار ترې اخلى، او هغه طاقتور لرې کوى چې ډېر وخت يې حکومت کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12160, 'Job 12:20', 'Job', 12, 20, '&nbsp;هغه اعتبارى مشيران غلى کړى، د مشرانو نه حِکمت يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12161, 'Job 12:21', 'Job', 12, 21, '&nbsp;هغه شهزادګان سپک کړى، او هغه د زورَورو زور اوبۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12162, 'Job 12:22', 'Job', 12, 22, '&nbsp;هغه د قبر تيارۀ لرې کوى، او هغه تکه توره تيارۀ په رڼا بدلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12163, 'Job 12:23', 'Job', 12, 23, '&nbsp;هغه قومونه تکړه کړى او بيا يې تباه کړى، هغه قومونه لوئ کړى او بيا يې پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12164, 'Job 12:24', 'Job', 12, 24, '&nbsp;هغه د دُنيا د مشرانو نه پوهه ختموى، او پرې يې ږدى چې سرګردانه او پرېشانه ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12165, 'Job 12:25', 'Job', 12, 25, '&nbsp;هغه مشران په تيارۀ کښې د ړندو په شان سرګردانه ګرځى، او د شرابى په شان يې ځنګېدلے کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12166, 'Job 13:1', 'Job', 13, 1, '&nbsp;ګوره، زما سترګو دا هر څۀ ليدلى دى، او زما غوږُونو دا اورېدلى دى او پوهه شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12167, 'Job 13:2', 'Job', 13, 2, '&nbsp;چې تا ته د څۀ پته ده نو ما ته هم د هغې پته ده، زۀ تا نه څۀ کم نۀ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12168, 'Job 13:3', 'Job', 13, 3, '&nbsp;خو زۀ به د قادر خُدائ سره خبره وکړم، او زۀ غواړم چې هغۀ ته خپل ځان بې‌ګناه ثابت کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12169, 'Job 13:4', 'Job', 13, 4, '&nbsp;د حقيقت پټولو دپاره تاسو دروغ وايئ، او تاسو د بې‌کاره طبيبانو په شان يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12170, 'Job 13:5', 'Job', 13, 5, '&nbsp;مړه کۀ تاسو خولې بندې کړئ، نو دا به ستاسو عقلمندى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12171, 'Job 13:6', 'Job', 13, 6, '&nbsp;اوس تاسو زما بحث واورئ، او زما زارۍ واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12172, 'Job 13:7', 'Job', 13, 7, '&nbsp;تاسو هغه څۀ وايئ څۀ چې خُدائ پاک نۀ دى وئيلى، او تاسو د هغۀ د خاطره د دوکې خبرې کوئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12173, 'Job 13:8', 'Job', 13, 8, '&nbsp;تاسو به د هغۀ طرفدارى کوئ څۀ، تاسو به د خُدائ پاک صفائى کوئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12174, 'Job 13:9', 'Job', 13, 9, '&nbsp;دا به ستاسو دپاره ښۀ وى څۀ چې هغه ستاسو آزمېښت وکړى؟ يا تاسو هغه داسې دوکه کولے شئ، لکه چې تاسو نور کسان دوکه کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12175, 'Job 13:10', 'Job', 13, 10, '&nbsp;هغه به بې‌شکه تاسو ورَټى کۀ تاسو په پټه طرفدارى وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12176, 'Job 13:11', 'Job', 13, 11, '&nbsp;د هغۀ د شان نه به تاسو يرېږئ نه څۀ، او د هغۀ يره به په تاسو باندې غالبه نۀ شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12177, 'Job 13:12', 'Job', 13, 12, '&nbsp;ستاسو قيصې او متلونه د ايرو په شان بې‌کاره دى، او ستاسو خبرې د خټې د لوښو په شان کچه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12178, 'Job 13:13', 'Job', 13, 13, '&nbsp;تاسو غلى شئ او ما له د خبرو کولو موقع راکړئ، نو چې څۀ کيږى هغه دې په ما وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12179, 'Job 13:14', 'Job', 13, 14, '&nbsp;زۀ به خپل ژوند په خطره کښې واچوم، او د خپل زړۀ خبره به وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12180, 'Job 13:15', 'Job', 13, 15, '&nbsp;کۀ هغه ما وژنى هم خو زۀ به په هغۀ توکل کوم، او زۀ به د هغۀ په مخکښې خپله دفاع کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12181, 'Job 13:16', 'Job', 13, 16, '&nbsp;او داسې به زۀ بچ شم ځکه چې زۀ څۀ کافر خو نۀ يم کۀ زۀ وم نو بيا به زۀ د هغۀ په مخکښې نۀ شوم ودرېدے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12182, 'Job 13:17', 'Job', 13, 17, '&nbsp;زما خبره په غور سره واورئ، او تاسو ما ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12183, 'Job 13:18', 'Job', 13, 18, '&nbsp;ګورئ، ما د خپلې خبرې تيارے کړے دے، ما ته پته ده چې زۀ به بې‌ګناه ثابت شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12184, 'Job 13:19', 'Job', 13, 19, '&nbsp;څوک ما سره په دې باندې بحث کولے شى؟ کۀ څوک ما غلط ثابت کړى نو زۀ به خاموش شم او مړ به شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12185, 'Job 13:20', 'Job', 13, 20, '&nbsp;اے خُدايه، ما له صِرف دوه څيزونه راکړه، نو بيا به زۀ خپل ځان ستا نه نۀ پټوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12186, 'Job 13:21', 'Job', 13, 21, '&nbsp;خپله سزا زما نه لرې کړه، او په خپله يره باندې ما مۀ يروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12187, 'Job 13:22', 'Job', 13, 22, '&nbsp;بيا ما ته آواز وکړه او زۀ به جواب درکړم، يا ما له اجازت راکړه چې خبرې وکړم او تۀ ما له د هغې جواب راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12188, 'Job 13:23', 'Job', 13, 23, '&nbsp;زما غلطيانې او زما ګناهونه څومره دى؟ ما ته زما بغاوت او زما ګناه وښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12189, 'Job 13:24', 'Job', 13, 24, '&nbsp;تۀ خپل مخ ولې پټوې، او تۀ ما خپل دشمن ولې ګڼې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12190, 'Job 13:25', 'Job', 13, 25, '&nbsp;زۀ خو هيڅ هم نۀ يم، نو تۀ ما ولې يروې؟ زۀ خو داسې يم لکه چې په هوا کښې پاڼې خوَزى دوړې الوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12191, 'Job 13:26', 'Job', 13, 26, '&nbsp;ځکه چې تۀ زما خِلاف ترخې خبرې ليکې، او تۀ ما له د ځوانۍ د ګناه سزا راکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12192, 'Job 13:27', 'Job', 13, 27, '&nbsp;تۀ زما پښې په زولنو کښې تړې، او تۀ زما په ټول چال چلن نظر ساتې، او زما د پښو چاپونه هم معلوموې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12193, 'Job 13:28', 'Job', 13, 28, '&nbsp;زۀ د سخا څيزونو په شان خراب شوے يم، د هغه جامو په شان چې چينجو خوړلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12194, 'Job 14:1', 'Job', 14, 1, '&nbsp;يو فانى انسان، د مور د خېټې نه پېدا، د يو څو ورځو مېلمه او د تکليفونو نه ډک،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12195, 'Job 14:2', 'Job', 14, 2, '&nbsp;د يو ګل په شان راوټوکيږى او مړاوے شى، هغه د سورى په شان منډه وهى زر زر ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12196, 'Job 14:3', 'Job', 14, 3, '&nbsp;تۀ په يو کمزورى مخلوق باندې نظر ساتې؟ او تۀ ما سره عدالت کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12197, 'Job 14:4', 'Job', 14, 4, '&nbsp;د يو ناپاک څيز نه څوک پاک څيز راويستلے شى؟ دا کار هيڅ څوک هم نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12198, 'Job 14:5', 'Job', 14, 5, '&nbsp;ځکه چې د هغوئ د عُمر حد مقرر دے، او د هغوئ د مياشتو شمېر تا ته معلوم دے، او دا تا مقررې کړې دى او دا نۀ شى بدلېدلے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12199, 'Job 14:6', 'Job', 14, 6, '&nbsp;نو مونږ پرېږده چې آرام وکړُو. مونږ د مزدورانو په شان يُو او مونږ پرېږده چې خپل کار په خېر ختم کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12200, 'Job 14:7', 'Job', 14, 7, '&nbsp;کۀ يوه ونه هم راوغورزولے شى، نو امکان شته دا به بيا راوشى، او د دې شنۀ کېدل به نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');